{'content': '/*
    Print-in-place Planetary Gearbox
    Constraints: 0.1mm layer height, 0.4mm nozzle
    Clearance: 0.3mm (horizontal) 0.2mm (vertical)
    Tapered gears for capture and 45-degree overhang compliance.
*/

$fn = 60;

// Parameters
sun_teeth = 12;
planet_teeth = 12;
ring_teeth = sun_teeth + 2 * planet_teeth; // 36
module_val = 2; // Size factor
clearance = 0.3; // Horizontal gap
v_clearance = 0.2; // Vertical gaps for moving parts
height = 10;
bore = 5;

// Calculated radii
sun_r = (sun_teeth * module_val) / 2;
planet_r = (planet_teeth * module_val) / 2;
ring_r = (ring_teeth * module_val) / 2;
orbit_r = sun_r + planet_r;

module herringbone_gear(teeth, r, h, internal=false) {
    // Simplified gear shape for printability (tapered for capture)
    // We use a double cone (diamond) profile to capture gears vertically
    // while maintaining 45 degree overhangs.

    translate([0,0,h/2])
    union() {
        // Upper half
        cylinder(h=h/2, r1=r, r2=r-h/2);
        // Lower half
        mirror([0,0,1])
        cylinder(h=h/2, r1=r, r2=r-h/2);
    }
}

module planetary_gearbox() {
    // 1. Ring Gear (Outer Housing)
    difference() {
        // Outer body
        cylinder(h=height, r=ring_r + 4);

        // Internal ring gear cavity (with 45 deg taper capture)
        translate([0,0,height/2])
        union() {
            cylinder(h=height/2 + 0.1, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
            mirror([0,0,1])
            cylinder(h=height/2 + 0.1, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
        }
    }

    // 2. Sun Gear
    difference() {
        union() {
            // Main gear body
            translate([0,0,height/2])
            union() {
                cylinder(h=height/2, r1=sun_r - clearance, r2=sun_r - clearance - height/2);
                mirror([0,0,1])
                cylinder(h=height/2, r1=sun_r - clearance, r2=sun_r - clearance - height/2);
            }
            // Sun gear extension/shaft
            translate([0,0,height]) cylinder(h=4, r=bore/2 + 2);
        }
        // Center bore
        translate([0,0,-1]) cylinder(h=height+10, r=bore/2);
    }

    // 3. Planet Gears (3 total)
    for (i = [0:2]) {
        angle = i * 120;
        rotate([0, 0, angle])
        translate([orbit_r, 0, 0]) {
            translate([0,0,height/2])
            union() {
                cylinder(h=height/2, r1=planet_r - clearance, r2=planet_r - clearance - height/2);
                mirror([0,0,1])
                cylinder(h=height/2, r1=planet_r - clearance, r2=planet_r - clearance - height/2);
            }
        }
    }

    // 4. Planet Carrier (Connecting the planets)
    // This is the tricky part for print-in-place.
    // We will place a "disc" at the bottom that connects to the planets via axles.
    // The disc must be suspended by 1 layer (0.1mm-0.2mm) to prevent fusion.

    carrier_z = -3;
    carrier_thickness = 2;

    render_carrier = true;
    if (render_carrier) {
        difference() {
            union() {
                // Bottom carrier plate
                translate([0, 0, -v_clearance - carrier_thickness])
                cylinder(h=carrier_thickness, r=ring_r + 2);

                // Axles for planets
                for (i = [0:2]) {
                    angle = i * 120;
                    rotate([0, 0, angle])
                    translate([orbit_r, 0, -v_clearance - carrier_thickness])
                    cylinder(h=height + v_clearance + carrier_thickness - 1, r=planet_r/3);
                }
            }
            // Sun gear clearance hole
            translate([0,0,-10]) cylinder(h=20, r=sun_r + clearance);

            // Cutouts for accessibility
            for (i=[0:2]) rotate([0,0,i*120+60]) translate([orbit_r, 0, -10]) cylinder(h=20, r=planet_r);
        }
    }
}

planetary_gearbox();
'}

{'content': '/*
    Full Print-in-place Planetary Gearbox
    Optimized for 0.4mm nozzle and 0.1mm layer height.
    Captures gears using a double-taper (V-shape) profile.
    Overhangs are 45 degrees or less.
    Clearance: 0.35mm horizontal, 0.4mm vertical.
*/

$fn = 64;

// Parameters
teeth_sun = 12;
teeth_planet = 12;
teeth_ring = 36;
m = 1.3; // module
clearance = 0.35; // Horizontal air gap
v_gap = 0.4; // Vertical air gap

sun_r = (teeth_sun * m) / 2;
planet_r = (teeth_planet * m) / 2;
ring_r = (teeth_ring * m) / 2;
orbit_r = sun_r + planet_r;

height = 8;
taper_h = height / 2;

module v_gear_shape(r, h, internal=false) {
    // A gear profile that tapers inwards and then outwards to capture mates
    // Use r as the pitch radius. For internal, we subtract clearance.
    // For external, we subtract clearance.

    translate([0,0,h/2])
    union() {
        // Bottom half cone
        mirror([0,0,1])
        cylinder(h=h/2, r1=r, r2=r-h/2);
        // Top half cone
        cylinder(h=h/2, r1=r, r2=r-h/2);
    }
}

module gear_unit() {
    // The Assembly

    // 1. Ring Gear (Outer Housing)
    difference() {
        cylinder(h=height, r=ring_r + 4);
        // Interior V cavity for gears to sit in
        translate([0,0,height/2]) {
            cylinder(h=height/2 + 0.1, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
            mirror([0,0,1]) cylinder(h=height/2 + 0.1, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
        }
        // Center top/bottom opening
        translate([0,0,-1]) cylinder(h=height + 2, r=ring_r - 2);
    }

    // 2. Sun Gear
    difference() {
        union() {
            // Gear body
            v_gear_shape(sun_r - clearance, height);
            // Handle for sun gear
            translate([0,0,height]) cylinder(h=5, r=sun_r - clearance - 1);
        }
        // Bore
        translate([0,0,-1]) cylinder(h=height+7, r=sun_r/2);
    }

    // 3. Planet Gears
    for (i = [0:2]) {
        rotate([0,0,i*120])
        translate([orbit_r, 0, 0]) {
            v_gear_shape(planet_r - clearance, height);

            // Integrated planetary axle (to be captured by a carrier)
            // But to keep it print-in-place and simple, we rely on the 
            // V-profile for vertical capture.
        }
    }

    // 4. Carrier (Top)
    // The carrier connects the planets. To print in place, it must be above the planets
    // and have a gap before starting.
    carrier_height = 2;
    carrier_z = height + v_gap;

    translate([0,0,carrier_z])
    difference() {
        union() {
            // Main disc
            cylinder(h=carrier_height, r=orbit_r + planet_r/2);
            // Connecting rods down into the planet centers
            for(i=[0:2]) {
                rotate([0,0,i*120])
                translate([orbit_r, 0, -v_gap - 2])
                cylinder(h=v_gap + 2, r=planet_r/2);
            }
        }
        // Clearance for Sun shaft
        cylinder(h=carrier_height + 0.1, r=sun_r + clearance);
    }
}

gear_unit();
'}

