    Captures gears using a double-taper (V-shape) profile.
    Overhangs are 45 degrees or less.
    Clearance: 0.35mm horizontal, 0.4mm vertical.
*/

$fn = 64;

// Parameters
teeth_sun = 12;
teeth_planet = 12;
teeth_ring = 36;
m = 1.3; // module
clearance = 0.3; // Horizontal air gap
v_gap = 0.4; // Vertical air gap

sun_r = (teeth_sun * m) / 2;
planet_r = (teeth_planet * m) / 2;
ring_r = (teeth_ring * m) / 2;
orbit_r = sun_r + planet_r;

height = 6; // Reduced height for better stability during print
taper_h = height / 2;

module v_gear_shape(r, h) {
    // V-shaped profile for capture and printability
    translate([0,0,h/2])
    union() {
        cylinder(h=h/2, r1=r, r2=r-h/2);
        mirror([0,0,1])
        cylinder(h=h/2, r1=r, r2=r-h/2);
    }
}

module planetary_gearbox() {
    // 1. Ring Gear (Outer Housing)
    difference() {
        // Outer shell
        cylinder(h=height, r=ring_r + 4);

        // Inner V-cavity (Internal gear teeth placeholder)
        translate([0,0,height/2]) {
            cylinder(h=height/2 + 0.05, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
            mirror([0,0,1])
            cylinder(h=height/2 + 0.05, r1=ring_r + clearance, r2=ring_r + clearance - height/2);
        }

        // Circular opening for access
        translate([0,0,-1]) cylinder(h=height+2, r=ring_r - 2);
    }

    // 2. Sun Gear (Center)
    difference() {
        union() {
            v_gear_shape(sun_r - clearance, height);
            // Center handle/input
            translate([0,0,height]) cylinder(h=4, r=sun_r - clearance - 1);
        }
        // Hollow bore for saving material / shaft
        translate([0,0,-1]) cylinder(h=height+6, r=sun_r/2);
    }

    // 3. Planet Gears (captured)
    for (i = [0:2]) {
        rotate([0, 0, i * 120])
        translate([orbit_r, 0, 0]) {
            v_gear_shape(planet_r - clearance, height);

            // "Axle" stump for the carrier to attach to
            // We use a cone on top of the planet to allow carrier to bridge onto it.
            translate([0,0,height - 0.1])
            cylinder(h=v_gap + 0.1, r1=planet_r/3, r2=planet_r/3);
        }
    }

    // 4. Carrier (Top connection)
    // The carrier connects the planets together.
    // It's printed on top with a vertical gap.
    carrier_z = height + v_gap;
    carrier_thickness = 2;

    // Using a ring-shaped carrier to keep the sun gear accessible
    translate([0,0,carrier_z])
    difference() {
        union() {
            // Main disc
            cylinder(h=carrier_thickness, r=orbit_r + planet_r/3);

            // Connection to the pins of the planets
            for (i=[0:2]) {
                rotate([0,0,i*120])
                translate([orbit_r, 0, -v_gap])
                cylinder(h=v_gap, r=planet_r/3);
            }
        }
        // Hole for sun gear shaft
        translate([0,0,-1]) cylinder(h=carrier_thickness + 2, r=sun_r + clearance + 1);

        // Decorative cutouts for weight/visibility
        for (i=[0:2]) {
            rotate([0,0,i*120 + 60])
            translate([orbit_r * 0.8, 0, -1])
            cylinder(h=carrier_thickness + 2, r=planet_r/2);
        }
    }
}

planetary_gearbox();
